begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(23);
insert into public.clinics(id,name) values('81000000-0000-4000-8000-000000000001','Synthetic follow-up A'),('81000000-0000-4000-8000-000000000002','Synthetic follow-up B');
insert into auth.users(id) values('82000000-0000-4000-8000-000000000001'),('82000000-0000-4000-8000-000000000002');
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('81000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','reception',true),('81000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000002','manager',true);
insert into public.inquiries(id,clinic_id,owner_user_id,display_name,contact_email,source,follow_up_at) values('83000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','Synthetic Owner','synthetic@example.test','phone','2030-01-01T00:00:00Z'),('83000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000002','82000000-0000-4000-8000-000000000001','Synthetic Foreign',null,'phone',null);
select is((select enabled from private.intake_command_settings),false,'commands default off');
select ok(not has_table_privilege('authenticated','private.inquiry_follow_ups','INSERT'),'no direct client writes');
select ok(not has_function_privilege('anon','public.record_inquiry_follow_up(uuid,uuid,uuid,jsonb,uuid)','EXECUTE'),'anonymous cannot execute command');
select set_config('request.jwt.claim.sub','82000000-0000-4000-8000-000000000001',true);
select set_config('request.method','POST',true);
set local role authenticated;
select throws_ok($$select public.record_inquiry_follow_up('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','{"kind":"contact_attempt","channel":"phone"}','85000000-0000-4000-8000-000000000001')$$,'PT503',null,'DB gate enforced');
select is(jsonb_array_length(public.list_inquiry_follow_ups('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001')->'items'),0,'authorized empty history readable while disabled');
reset role;
update private.intake_command_settings set enabled=true;
set local role authenticated;
select is(public.record_inquiry_follow_up('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','{"kind":"contact_attempt","channel":"phone"}','85000000-0000-4000-8000-000000000001')->>'replayed','false','new attestation persisted');
select is((select status from public.inquiries where id='83000000-0000-4000-8000-000000000001'),'new','inquiry status unchanged');
select is((select follow_up_at from public.inquiries where id='83000000-0000-4000-8000-000000000001'),'2030-01-01T00:00:00Z'::timestamptz,'original due date unchanged');
select is(public.record_inquiry_follow_up('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','{"kind":"contact_attempt","channel":"phone"}','85000000-0000-4000-8000-000000000001')->>'replayed','true','exact replay');
select throws_ok($$select public.record_inquiry_follow_up('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','{"kind":"contact_attempt","channel":"email"}','85000000-0000-4000-8000-000000000001')$$,'PT409',null,'changed payload conflicts');
select throws_ok($$select public.list_inquiry_follow_ups('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000002')$$,'PT404',null,'foreign inquiry concealed');
select set_config('request.jwt.claim.sub','82000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.list_inquiry_follow_ups('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001')$$,'42501',null,'another active manager is not owner');
reset role;
update public.inquiries set owner_user_id='82000000-0000-4000-8000-000000000002' where id='83000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','82000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.record_inquiry_follow_up('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','{"kind":"contact_attempt","channel":"phone"}','85000000-0000-4000-8000-000000000001')$$,'42501',null,'former owner cannot replay even while active');
reset role;
update public.inquiries set owner_user_id='82000000-0000-4000-8000-000000000001' where id='83000000-0000-4000-8000-000000000001';
update public.clinic_memberships set active=false where user_id='82000000-0000-4000-8000-000000000001';
-- Superuser caller still cannot bypass explicit membership authorization.
select throws_ok($$select public.list_inquiry_follow_ups('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001')$$,'42501',null,'privileged path rechecks revoked membership');
update public.clinic_memberships set active=true where user_id='82000000-0000-4000-8000-000000000001';
select throws_ok($$select public.record_inquiry_follow_up('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000002','{"kind":"contact_attempt","channel":"phone","note":"secret"}','85000000-0000-4000-8000-000000000001')$$,'22023',null,'extra contact/free-text fields denied');
select throws_ok($$update private.inquiry_follow_ups set channel='email'$$,'55000',null,'history cannot be silently edited');
select throws_ok($$delete from private.inquiry_follow_ups$$,'55000',null,'history cannot be silently deleted');
create function private.fail_follow_up_test() returns trigger language plpgsql as $$begin raise exception 'synthetic failure';end$$;
create trigger fail_follow_up_test before insert on private.outbox_events for each row execute function private.fail_follow_up_test();
select throws_ok($$select public.record_inquiry_follow_up('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000002','{"kind":"contact_attempt","channel":"phone"}','85000000-0000-4000-8000-000000000001')$$,'P0001','synthetic failure','sink failure rolls back command');
select is((select count(*)::integer from private.inquiry_follow_ups where clinic_id='81000000-0000-4000-8000-000000000001'),1,'failed command left no record');
select is((select payload-'follow_up_id'-'inquiry_id'-'kind'-'channel'-'recorded_at' from private.outbox_events where clinic_id='81000000-0000-4000-8000-000000000001'),'{}'::jsonb,'event payload contains only approved minimal fields');
drop trigger fail_follow_up_test on private.outbox_events;
drop function private.fail_follow_up_test();
insert into private.inquiry_follow_ups(id,clinic_id,inquiry_id,actor_user_id,kind,channel,recorded_at) select ('86000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','contact_attempt','phone','2030-01-01Z' from generate_series(1,51)n;
set local role authenticated;
select is(jsonb_array_length(public.list_inquiry_follow_ups('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001')->'items'),50,'history bounded to50');
select is(public.list_inquiry_follow_ups('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001')->>'truncated','true','partial history explicit');
select is(public.list_inquiry_follow_ups('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001')->'items'->0->>'id','86000000-0000-4000-8000-000000000051','deterministic descending UUID tie break');
reset role;
select * from finish();
rollback;
